const GUIDES=[['1','Allestimento dell’acquario','Scelta della vasca, posizione stabile, fondo, rocce e legni. Sciacqua i materiali e usa solo elementi sicuri per acquari.','Avvio','▧'],['2','Maturazione','Il ciclo dell’azoto richiede tempo. Segui ammoniaca/ammonio e nitriti con test; non inserire fauna finché il ciclo non è verificato.','Avvio','◌'],['3','Valori dell’acqua','Come prelevare campioni, leggere pH, KH, GH, NO₂, NO₃ e interpretare risultati e intervalli adatti alla fauna.','Avvio','⚗'],['4','Piante','Scegli specie in base a luce, CO₂, substrato, temperatura e spazio adulto. Inserisci le piante senza coprire rizomi.','Avvio','♧'],['5','Inserimento dei pesci','Verifica compatibilità, volume, comportamento e parametri. Inserisci gli animali gradualmente solo con ciclo stabile.','Avvio','🐟'],['6','Manutenzione','Pianifica cambi d’acqua, controllo del filtro, potature e pulizia senza sterilizzare i materiali filtranti.','Gestione','🔧'],['7','Problemi comuni e alghe','Valuta luce, nutrienti, flusso, manutenzione e stabilità prima di usare trattamenti. Evita cambi drastici e prodotti inutili.','Gestione','✦'],['8','Fertilizzazione e CO₂','Adatta fertilizzanti alla massa vegetale, alla luce e ai segnali delle piante. Misura e annota le dosi: non aumentare tutto insieme.','Gestione','♧']];
const defaults={tank:{name:'Acquario principale',litres:'',type:'dolce',stage:'setup',startDate:'',equipment:{}},entries:[],myPlants:[],favorites:[]};
function load(){try{return Object.assign({},defaults,JSON.parse(localStorage.getItem('lineaAcquaData')||'{}'))}catch{return JSON.parse(JSON.stringify(defaults))}}
let data=load(), currentPlant=PLANTS[0], diaryFilter='Tutti', plantTab='recommended', plantFilter='tutte', guideFilter='Tutte', period=30, waterTab='current', tankTab='overview';
data.tank=Object.assign({},defaults.tank,data.tank||{});['entries','myPlants','favorites'].forEach(k=>{if(!Array.isArray(data[k]))data[k]=[]});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem('lineaAcquaData',JSON.stringify(data));renderAll()}
function localDT(){return new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}
function fmtDate(s){if(!s)return '—';let d=new Date(s);return isNaN(d)?'—':d.toLocaleString('it-IT',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function latest(p){return data.entries.filter(e=>e.type==='Test acqua'&&e.param===p&&e.value!==''&&Number.isFinite(Number(e.value))).sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0]}
function ideal(p){let x=PARAMS[p];return x?`${x.min}–${x.max}${x.unit}`:'—'}
function status(p,v){if(v===undefined||v===null||v==='')return ['Nessun dato','unknown'];let x=PARAMS[p],n=Number(v);if(!x||!Number.isFinite(n))return ['Da valutare','unknown'];return n>=x.min&&n<=x.max?['Nel range orientativo','good']:['Fuori dal range orientativo','warn']}
function go(id){if(id==='home'&&$('#splash').classList.contains('show'))$('#splash').classList.remove('show');$$('.page').forEach(p=>p.classList.toggle('active',p.id===id));const navId=({'water':'analysis','plant-detail':'plants','add-event':'diary','tank':'home','advice':'home'})[id]||id;$$('.bottomnav .navitem').forEach(b=>b.classList.toggle('active',b.dataset.go===navId));window.scrollTo({top:0,behavior:'smooth'});if(id==='analysis')renderAnalysis();if(id==='water')renderWater();if(id==='add-event')prepareEvent();}
$$('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
$$('[data-quick-action]').forEach(b=>b.addEventListener('click',()=>{const action=b.dataset.quickAction;go('add-event');if(action==='test'){document.querySelector('[data-event-type="Test acqua"]').click();setTimeout(()=>$('#entryParam').focus(),80)}else if(action==='activity'){document.querySelector('[data-event-type="Manutenzione"]').click();setTimeout(()=>$('#entryNotes').focus(),80)}else if(action==='photo'){document.querySelector('[data-event-type="Foto"]').click();setTimeout(()=>$('#entryPhoto').click(),120)}}));
function populateParams(){['#analysisParam','#waterGraphParam','#entryParam'].forEach(sel=>{let el=$(sel);if(el)el.innerHTML=Object.keys(PARAMS).map(p=>`<option>${p}</option>`).join('')})}
function renderHome(){let t=data.tank;$('#homeTankName').textContent=t.name||'Acquario principale';$('#homeTankDetails').textContent=`${t.litres?`${t.litres} litri`:'Volume non impostato'} · ${t.type==='marino'?'Acqua marina':t.type==='salmastra'?'Acqua salmastra':'Acqua dolce'}`;let labels={setup:'Allestimento',maturation:'Maturazione',stocked:'Con fauna'};$('#stageLabel').textContent=labels[t.stage]||labels.setup;$('#stageProgress').style.width=t.stage==='setup'?'12%':t.stage==='maturation'?'53%':'100%';let values=$('#homeValues');values.innerHTML='';['Temperatura','pH','KH','GH','NO2','NO3','NH3/NH4','PO4','Fe'].forEach(p=>{let e=latest(p),v=e?e.value:null,[st,cl]=status(p,v);let b=document.createElement('button');b.className='value-card '+(cl==='warn'?'warn':'');b.innerHTML=`<span class="param">${p}</span><div class="value">${v==null?'—':esc(v)}</div><span class="unit">${PARAMS[p].unit||' '}</span><i class="dot"></i>`;b.onclick=()=>showParam(p);values.append(b)});let measured=Object.keys(PARAMS).filter(p=>latest(p));let warnings=measured.filter(p=>status(p,latest(p).value)[1]==='warn');$('#overallTitle').textContent=!measured.length?'Inizia a monitorare':warnings.length?`${warnings.length} valore/i da controllare`:'Valori registrati nel range';$('#overallText').textContent=!measured.length?'Registra i primi test per seguire l’andamento dell’acqua.':warnings.length?'Verifica i risultati e le esigenze degli abitanti prima di intervenire.':'Controlla anche i valori non ancora misurati e la stabilità nel tempo.';$('#overallIcon').textContent=warnings.length?'!':'✓';$('#nextAction').textContent=!data.entries.length?'Registra i valori iniziali':t.stage==='maturation'?'Controlla il ciclo biologico':'Aggiorna il diario della vasca';$('#nextActionSub').textContent=t.stage==='maturation'?'Controlla NH₃/NH₄ e NO₂; non basarti solo sui giorni trascorsi.':'Annota test, manutenzione e cambi d’acqua.';$('#homeHint').textContent=warnings.length?'Un valore fuori range non richiede sempre un intervento immediato: verifica il test e il contesto.':'I valori ideali dipendono da specie, allestimento e obiettivi. Registra dati reali senza fretta.';$('#tankPlantCount').textContent=data.myPlants.length?`${data.myPlants.length} specie nella tua lista`:'Nessuna pianta registrata'}
function drawChart(canvasId,param,days,summaryId){let canvas=$(canvasId);if(!canvas)return;let ctx=canvas.getContext('2d'),w=canvas.clientWidth||320,h=canvas.clientHeight||220,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);let p=PARAMS[param],cut=Date.now()-days*86400000,arr=data.entries.filter(e=>e.type==='Test acqua'&&e.param===param&&e.value!==''&&new Date(e.date).getTime()>=cut).sort((a,b)=>a.date.localeCompare(b.date));ctx.strokeStyle='#164865';ctx.lineWidth=1;for(let i=1;i<5;i++){let y=i*h/5;ctx.beginPath();ctx.moveTo(28,y);ctx.lineTo(w-10,y);ctx.stroke()}if(p){let vals=arr.map(e=>Number(e.value)),min=Math.min(p.min,...vals),max=Math.max(p.max,...vals);if(max===min)max=min+1;let yval=v=>h-25-(v-min)/(max-min)*(h-48);ctx.fillStyle='#13d7a022';ctx.fillRect(28,yval(p.max),w-40,yval(p.min)-yval(p.max));ctx.strokeStyle='#25d8a0';ctx.setLineDash([4,4]);[p.min,p.max].forEach(v=>{ctx.beginPath();ctx.moveTo(28,yval(v));ctx.lineTo(w-10,yval(v));ctx.stroke()});ctx.setLineDash([]);if(arr.length){ctx.strokeStyle='#17d8f5';ctx.lineWidth=2.5;ctx.beginPath();arr.forEach((e,i)=>{let x=30+(w-45)*(arr.length===1?.5:i/(arr.length-1)),y=yval(Number(e.value));i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();arr.forEach((e,i)=>{let x=30+(w-45)*(arr.length===1?.5:i/(arr.length-1)),y=yval(Number(e.value));ctx.fillStyle='#8ff4ff';ctx.beginPath();ctx.arc(x,y,3.5,0,Math.PI*2);ctx.fill()})}ctx.fillStyle='#9cc9df';ctx.font='10px system-ui';ctx.fillText(String(max.toFixed(2)),3,13);ctx.fillText(String(min.toFixed(2)),3,h-8)}if(summaryId)$(summaryId).textContent=arr.length?`${arr.length} misurazioni nel periodo · ultima ${arr[arr.length-1].value}${p.unit} · range orientativo ${ideal(param)}`:'Nessuna misurazione registrata nel periodo selezionato.'}
function renderAnalysis(){let p=$('#analysisParam').value||'pH';drawChart('#chart',p,period,'#chartSummary');let measured=Object.keys(PARAMS).filter(k=>latest(k)),warn=measured.filter(k=>status(k,latest(k).value)[1]==='warn');$('#analysisOverall').textContent=!measured.length?'In attesa di misurazioni':warn.length?'Valori da verificare':'Valori registrati';$('#analysisStatusText').textContent=!measured.length?'Aggiungi i tuoi test per vedere grafici e statistiche.':warn.length?`${warn.length} parametro/i fuori dal range orientativo.`:'I parametri misurati sono nel range orientativo; continua a monitorarli.';let pEntries=data.entries.filter(e=>e.type==='Test acqua'&&e.param===p&&e.value!==''&&new Date(e.date).getTime()>=Date.now()-period*86400000).map(e=>Number(e.value));let avg=pEntries.length?pEntries.reduce((a,b)=>a+b,0)/pEntries.length:null;$('#analysisStats').innerHTML=[['Valore attuale',latest(p)?latest(p).value+PARAMS[p].unit:'—'],['Range ideale',ideal(p)],['Minimo',pEntries.length?Math.min(...pEntries):'—'],['Media',avg===null?'—':avg.toFixed(2)]].map(a=>`<div class="stat-card"><small>${a[0]}</small><strong>${a[1]}</strong><em>${a[0]==='Range ideale'?'Indicativo':pEntries.length?`${pEntries.length} dati nel periodo`:'Nessun dato'}</em></div>`).join('');$('#analysisList').innerHTML=Object.keys(PARAMS).map(k=>{let e=latest(k),[st,cl]=status(k,e?.value);return `<button data-param="${esc(k)}"><span class="list-icon">◉</span><span><strong>${esc(k)} · ${e?esc(e.value)+PARAMS[k].unit:'Nessun dato'}</strong><small>Ideale ${ideal(k)} · ${st}</small></span><b>›</b></button>`}).join('');$$('#analysisList [data-param]').forEach(b=>b.onclick=()=>showParam(b.dataset.param))}
function renderWater(){let arr=Object.keys(PARAMS);$('#waterCards').innerHTML=arr.map(p=>{let e=latest(p),v=e?e.value:null,[st,cl]=status(p,v);return `<button class="water-param ${cl==='warn'?'warn':''}" data-param="${esc(p)}"><header><span>${esc(p)}</span><span>›</span></header><div class="bigvalue">${v==null?'—':esc(v)}<small>${PARAMS[p].unit}</small></div><small>Ideale ${ideal(p)}</small><div class="state">${st}</div></button>`}).join('');$$('#waterCards [data-param]').forEach(b=>b.onclick=()=>showParam(b.dataset.param));$('#rangeList').innerHTML=arr.map(p=>`<button data-param="${esc(p)}"><span class="list-icon">◉</span><span><strong>${esc(p)}</strong><small>${PARAMS[p].desc} · range indicativo ${ideal(p)}</small></span><b>›</b></button>`).join('');$$('#rangeList [data-param]').forEach(b=>b.onclick=()=>showParam(b.dataset.param));drawChart('#waterChart',$('#waterGraphParam').value||'pH',30,'#waterGraphSummary')}
function renderDiary(){let arr=[...data.entries].sort((a,b)=>String(b.date).localeCompare(String(a.date)));if(diaryFilter!=='Tutti')arr=arr.filter(e=>e.type===diaryFilter||(diaryFilter==='Piante o fauna'&&e.type==='Fauna'));$('#diaryList').innerHTML=arr.length?arr.map(e=>{let d=new Date(e.date),date=Number.isNaN(+d)?{day:'—',month:''}:{day:d.toLocaleDateString('it-IT',{day:'2-digit'}),month:d.toLocaleDateString('it-IT',{month:'short'})};return `<article class="timeline-item"><div class="date-block"><strong>${date.day}</strong>${date.month}</div><div class="timeline-card"><header><strong>${esc(e.type)}${e.type==='Test acqua'?' · '+esc(e.param||''):''}</strong><time>${d&&!isNaN(+d)?d.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}):''}</time></header>${e.value!==undefined&&e.value!==''?`<p><b>${esc(e.value)}${PARAMS[e.param]?.unit||''}</b></p>`:''}${e.quantity?`<p>Quantità: ${esc(e.quantity)}</p>`:''}${e.notes?`<p>${esc(e.notes)}</p>`:''}${e.photo?`<img src="${e.photo}" alt="Foto evento" style="width:100%;max-height:160px;object-fit:cover;border-radius:8px;margin-top:8px">`:''}<button class="deletebtn" data-delete="${esc(e.id)}">Elimina voce</button></div></article>`}).join(''):'<div class="panel muted">Non ci sono voci in questa categoria. Premi + per registrare il primo evento.</div>';$$('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Eliminare questa voce dal diario e dallo storico delle analisi?')){data.entries=data.entries.filter(e=>e.id!==b.dataset.delete);save()}})}

