const plantPhotoCache = {};
const plantPhotoPending = new Set();
async function resolvePlantPhoto(plant){
  if(plantPhotoCache[plant.name] || plantPhotoPending.has(plant.name)) return;
  plantPhotoPending.add(plant.name);
  const botanical = plant.name.replace(/\s*\([^)]*\)/g,'').trim();
  try{
    let photo = '';
    const wiki = 'https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&prop=pageimages&pithumbsize=640&titles='+encodeURIComponent(botanical);
    const response = await fetch(wiki, {mode:'cors'});
    if(response.ok){
      const json=await response.json();
      const pages=Object.values(json.query?.pages||{});
      const page=pages.find(x=>x.title?.toLowerCase()===botanical.toLowerCase() && x.thumbnail?.source);
      if(page) photo=page.thumbnail.source;
    }
    if(!photo){
      const commons='https://commons.wikimedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrnamespace=6&gsrlimit=10&gsrsearch='+encodeURIComponent('intitle:"'+botanical+'"')+'&prop=imageinfo&iiprop=url&iiurlwidth=640';
      const r=await fetch(commons,{mode:'cors'});
      if(r.ok){
        const j=await r.json();
        const files=Object.values(j.query?.pages||{});
        const normalized=botanical.toLowerCase().replace(/[^a-z0-9]/g,'');
        const matched=files.find(x=>x.title?.toLowerCase().replace(/[^a-z0-9]/g,'').includes(normalized) && x.imageinfo?.[0]?.thumburl && /\.(jpg|jpeg|png|webp)$/i.test(x.title));
        if(matched) photo=matched.imageinfo[0].thumburl;
      }
    }
    if(photo){
      plantPhotoCache[plant.name]=photo;
      document.querySelectorAll('img[data-plant-photo]').forEach(img=>{
        if(img.dataset.plantPhoto===plant.name){img.src=photo;img.onerror=()=>{img.onerror=null;img.src=plant.img;};}
      });
    }
  }catch(err){ /* La PWA resta utilizzabile anche offline. */ }
  finally{plantPhotoPending.delete(plant.name);}
}
function refreshPlantPhotos(){
  document.querySelectorAll('img[data-plant-photo]').forEach(img=>{
    const plant=PLANTS.find(p=>p.name===img.dataset.plantPhoto);
    if(!plant)return;
    if(plantPhotoCache[plant.name])img.src=plantPhotoCache[plant.name];
    else resolvePlantPhoto(plant);
  });
}
